"""Money handling and the kitty's bookkeeping rules.

All money in the main currency is kept as whole cents (ints) while
calculating, so totals always add up exactly. In kitty.json it is stored
as text with two decimals, the same way it is printed.
"""

import json
import os
import re
import tempfile
from datetime import date, datetime
from decimal import ROUND_HALF_UP, Decimal, InvalidOperation
from fractions import Fraction

DATA_FILE = "kitty.json"
DEFAULT_CATEGORY = "other"


class KittyError(Exception):
    """A problem caused by user input; shown as a message, not a crash."""


# ---------------------------------------------------------------- parsing

def parse_number(text, what):
    """Parse a plain decimal number such as '45' or '0.92'."""
    cleaned = text.strip()
    try:
        value = Decimal(cleaned)
    except InvalidOperation:
        value = None
    if value is None or not value.is_finite() or "_" in cleaned:
        raise KittyError("{} must be a number, got '{}'".format(what, text))
    return value


def parse_positive(text, what):
    value = parse_number(text, what)
    if value <= 0:
        raise KittyError("{} must be more than zero, got '{}'".format(what, text))
    return value


def parse_money(text, what="amount"):
    """Parse a positive amount of money with at most two decimals."""
    value = parse_positive(text, what)
    if value != value.quantize(Decimal("0.01")):
        raise KittyError(
            "{} can have at most two decimals, got '{}'".format(what, text))
    return value


def parse_currency(text):
    code = text.strip().upper()
    if not re.fullmatch(r"[A-Z]{3}", code):
        raise KittyError(
            "currency must be a three-letter code like EUR or USD, got '{}'"
            .format(text))
    return code


def parse_date(text):
    try:
        return datetime.strptime(text.strip(), "%Y-%m-%d").date().isoformat()
    except ValueError:
        raise KittyError(
            "date must be a real date written like 2026-07-14, got '{}'"
            .format(text))


def today():
    return date.today().isoformat()


# ------------------------------------------------------------------ money

def to_cents(value):
    """Round a Decimal amount to whole cents (half up)."""
    return int((value * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def fmt(cents):
    """Format cents as text with two decimals, e.g. -2070 -> '-20.70'."""
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return "{}{}.{:02d}".format(sign, cents // 100, cents % 100)


def cents_of(text):
    """Read a two-decimal amount stored in kitty.json back into cents."""
    return to_cents(Decimal(text))


def allocate(total, weights):
    """Split `total` cents in proportion to `weights`.

    The parts always add up to exactly `total`: everyone gets their part
    rounded down, then the leftover cents go one each to people in the order
    they are listed. (There are always fewer leftover cents than people.)
    """
    weights = [Fraction(w) for w in weights]
    weight_sum = sum(weights)
    parts = [int(total * w // weight_sum) for w in weights]
    leftover = total - sum(parts)
    for i in range(leftover):
        parts[i] += 1
    return parts


# ---------------------------------------------------------------- storage

def new_kitty(currency):
    return {
        "version": 1,
        "currency": currency,
        "members": [],
        "rates": {},
        "expenses": [],
        "payments": [],
        "next_expense_id": 1,
        "next_payment_id": 1,
        "next_seq": 1,
    }


def load(path=DATA_FILE):
    if not os.path.exists(path):
        raise KittyError(
            "there's no kitty in this folder yet. Start one with: "
            "python3 -m kitty init EUR")
    try:
        with open(path, encoding="utf-8") as f:
            data = json.load(f)
    except (OSError, ValueError) as e:
        raise KittyError("couldn't read {}: {}".format(path, e))
    if not isinstance(data, dict) or data.get("version") != 1:
        raise KittyError("{} doesn't look like a kitty file".format(path))
    return data


def save(data, path=DATA_FILE):
    """Write the file safely: a half-written file never replaces a good one."""
    folder = os.path.dirname(os.path.abspath(path))
    fd, tmp = tempfile.mkstemp(dir=folder, prefix=".kitty-", suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, ensure_ascii=False)
            f.write("\n")
        os.replace(tmp, path)
    except BaseException:
        if os.path.exists(tmp):
            os.remove(tmp)
        raise


# ---------------------------------------------------------------- members

def validate_new_name(data, name):
    name = name.strip()
    if not name:
        raise KittyError("a name can't be empty")
    if "," in name or "=" in name:
        raise KittyError("a name can't contain ',' or '=', got '{}'".format(name))
    if name.startswith("-"):
        raise KittyError("a name can't start with '-', got '{}'".format(name))
    for existing in data["members"]:
        if existing.lower() == name.lower():
            raise KittyError("'{}' is already in the group".format(existing))
    return name


def require_member(data, name):
    name = name.strip()
    if name in data["members"]:
        return name
    message = "'{}' is not in the group".format(name)
    for existing in data["members"]:
        if existing.lower() == name.lower():
            message += " (did you mean '{}'?)".format(existing)
            break
    else:
        if data["members"]:
            message += " (members: {})".format(", ".join(data["members"]))
        else:
            message += " (nobody has been added yet)"
    raise KittyError(message)


def is_involved(data, name):
    for e in data["expenses"]:
        if e["payer"] == name or name in e["shares"]:
            return True
    for p in data["payments"]:
        if name in (p["from"], p["to"]):
            return True
    return False


# ------------------------------------------------------------- currencies

def rate_for(data, currency):
    if currency == data["currency"]:
        return Decimal(1)
    if currency not in data["rates"]:
        raise KittyError(
            "there's no exchange rate for {0} yet. Set one first, e.g.: "
            "python3 -m kitty rate set {0} 0.92".format(currency))
    return Decimal(data["rates"][currency])


def to_base_cents(data, amount, currency):
    cents = to_cents(amount * rate_for(data, currency))
    if cents <= 0:
        raise KittyError(
            "{} {} is less than one cent in {}".format(
                amount, currency, data["currency"]))
    return cents


# ---------------------------------------------------------------- splits

def parse_name_list(data, text, option):
    names = [require_member(data, n) for n in text.split(",") if n.strip()]
    if not names:
        raise KittyError("{} needs at least one name".format(option))
    if len(set(names)) != len(names):
        raise KittyError("{} lists someone twice".format(option))
    return names


def parse_name_values(data, text, option, parse_value):
    """Parse 'A=30,B=20' into [(name, Decimal), ...]."""
    pairs = []
    for item in text.split(","):
        if not item.strip():
            continue
        name, sep, value = item.partition("=")
        if not sep:
            raise KittyError(
                "{} expects NAME=VALUE pairs like Alice=30,Bob=20, got '{}'"
                .format(option, item.strip()))
        name = require_member(data, name)
        pairs.append((name, parse_value(value, "{} value for {}".format(option, name))))
    if not pairs:
        raise KittyError("{} needs at least one NAME=VALUE pair".format(option))
    names = [n for n, _ in pairs]
    if len(set(names)) != len(names):
        raise KittyError("{} lists someone twice".format(option))
    return pairs


def compute_shares(data, base_cents, amount, currency,
                   among=None, exact=None, shares=None, percent=None):
    """Work out each person's share (in cents of the main currency)."""
    chosen = [opt for opt, val in (("--among", among), ("--exact", exact),
                                   ("--shares", shares), ("--percent", percent))
              if val is not None]
    if len(chosen) > 1:
        raise KittyError("use only one of {}".format(", ".join(chosen)))

    if exact is not None:
        pairs = parse_name_values(data, exact, "--exact", parse_money)
        total = sum(v for _, v in pairs)
        if total != amount:
            raise KittyError(
                "--exact amounts add up to {} but the expense is {} {}".format(
                    total.quantize(Decimal("0.01")),
                    amount.quantize(Decimal("0.01")), currency))
    elif shares is not None:
        pairs = parse_name_values(data, shares, "--shares", parse_positive)
    elif percent is not None:
        pairs = parse_name_values(data, percent, "--percent", parse_positive)
        total = sum(v for _, v in pairs)
        if total != 100:
            raise KittyError(
                "--percent values add up to {} but must add up to 100"
                .format(total.normalize()))
    else:
        names = (parse_name_list(data, among, "--among") if among is not None
                 else list(data["members"]))
        if not names:
            raise KittyError("there's nobody in the group to split this between")
        pairs = [(n, Decimal(1)) for n in names]

    # Split in the order the names were typed (that decides who gets leftover
    # cents), then show them in the group's order so lists look consistent.
    parts = allocate(base_cents, [w for _, w in pairs])
    order = {name: i for i, name in enumerate(data["members"])}
    return {name: part for (name, _), part
            in sorted(zip(pairs, parts), key=lambda p: order[p[0][0]])}


# ---------------------------------------------------------------- reports

def balances(data):
    result = {name: 0 for name in data["members"]}
    for e in data["expenses"]:
        result[e["payer"]] += cents_of(e["base_amount"])
        for name, share in e["shares"].items():
            result[name] -= cents_of(share)
    for p in data["payments"]:
        result[p["from"]] += cents_of(p["base_amount"])
        result[p["to"]] -= cents_of(p["base_amount"])
    return result


def settle(data):
    """Suggest payments that bring everyone back to zero.

    Repeatedly has the person who owes the most pay the person who is owed
    the most, which keeps the number of payments small.
    """
    order = {name: i for i, name in enumerate(data["members"])}
    owed = {n: c for n, c in balances(data).items() if c > 0}
    owes = {n: -c for n, c in balances(data).items() if c < 0}
    transfers = []
    while owed and owes:
        creditor = min(owed, key=lambda n: (-owed[n], order[n]))
        debtor = min(owes, key=lambda n: (-owes[n], order[n]))
        amount = min(owed[creditor], owes[debtor])
        transfers.append({"from": debtor, "to": creditor, "amount": fmt(amount)})
        owed[creditor] -= amount
        owes[debtor] -= amount
        if owed[creditor] == 0:
            del owed[creditor]
        if owes[debtor] == 0:
            del owes[debtor]
    return transfers


def history(data, name):
    events = []
    for e in data["expenses"]:
        if e["payer"] != name and name not in e["shares"]:
            continue
        change = -cents_of(e["shares"].get(name, "0"))
        if e["payer"] == name:
            change += cents_of(e["base_amount"])
        events.append((e["date"], e["seq"], e["description"], change))
    for p in data["payments"]:
        if p["from"] == name:
            events.append((p["date"], p["seq"], "Payment to " + p["to"],
                           cents_of(p["base_amount"])))
        elif p["to"] == name:
            events.append((p["date"], p["seq"], "Payment from " + p["from"],
                           -cents_of(p["base_amount"])))
    events.sort(key=lambda ev: (ev[0], ev[1]))
    running = 0
    rows = []
    for day, _, description, change in events:
        running += change
        rows.append({"date": day, "description": description,
                     "change": fmt(change), "balance": fmt(running)})
    return rows


def category_report(data):
    order = {name: i for i, name in enumerate(data["members"])}
    totals = {}
    for e in data["expenses"]:
        per_person = totals.setdefault(e["category"], {})
        for name, share in e["shares"].items():
            per_person[name] = per_person.get(name, 0) + cents_of(share)
    return {
        category: {name: fmt(cents) for name, cents
                   in sorted(totals[category].items(), key=lambda kv: order[kv[0]])}
        for category in sorted(totals)
    }
"""Command-line interface: `python3 -m kitty COMMAND ...`.

Reports are printed as JSON. Commands that only change the kitty print
nothing when they succeed, except `expense add`, which prints the new ID.
Any mistake prints "error: ..." and exits with status 1.
"""

import argparse
import csv
import json
import os
import sys

from . import core
from .core import KittyError, fmt


class Parser(argparse.ArgumentParser):
    """An argument parser that exits with status 1 on bad usage."""

    def error(self, message):
        self.print_usage(sys.stderr)
        self.exit(1, "error: {}\n".format(message))


# --------------------------------------------------------------- commands

def cmd_init(args):
    if os.path.exists(core.DATA_FILE):
        raise KittyError(
            "there's already a kitty in this folder ({}). Delete or move that "
            "file first if you really want to start over".format(core.DATA_FILE))
    core.save(core.new_kitty(core.parse_currency(args.currency)))


def cmd_member_add(args, data):
    data["members"].append(core.validate_new_name(data, args.name))


def cmd_member_remove(args, data):
    name = core.require_member(data, args.name)
    if core.is_involved(data, name):
        raise KittyError(
            "{} is part of expenses or payments already, so they can't be "
            "removed (remove those first)".format(name))
    data["members"].remove(name)


def cmd_member_list(args, data):
    return data["members"]


def cmd_expense_add(args, data):
    payer = core.require_member(data, args.payer)
    amount = core.parse_money(args.amount)
    currency = (core.parse_currency(args.currency) if args.currency
                else data["currency"])
    description = " ".join(args.description).strip()
    if not description:
        raise KittyError("the description can't be empty")
    category = (args.category or core.DEFAULT_CATEGORY).strip()
    if not category:
        raise KittyError("the category can't be empty")
    day = core.parse_date(args.date) if args.date else core.today()

    base_cents = core.to_base_cents(data, amount, currency)
    shares = core.compute_shares(data, base_cents, amount, currency,
                                 among=args.among, exact=args.exact,
                                 shares=args.shares, percent=args.percent)

    expense_id = data["next_expense_id"]
    data["next_expense_id"] += 1
    data["expenses"].append({
        "id": expense_id,
        "date": day,
        "payer": payer,
        "description": description,
        "amount": "{:.2f}".format(amount),
        "currency": currency,
        "base_amount": fmt(base_cents),
        "category": category,
        "shares": {name: fmt(c) for name, c in shares.items()},
        "seq": next_seq(data),
    })
    return expense_id


def public_expense(e):
    return {key: e[key] for key in ("id", "date", "payer", "description",
                                    "amount", "currency", "base_amount",
                                    "category", "shares")}


def cmd_expense_list(args, data):
    return [public_expense(e) for e in data["expenses"]]


def cmd_expense_remove(args, data):
    try:
        expense_id = int(args.id)
    except ValueError:
        raise KittyError("expense ID must be a whole number, got '{}'".format(args.id))
    for e in data["expenses"]:
        if e["id"] == expense_id:
            data["expenses"].remove(e)
            return None
    raise KittyError("there's no expense with ID {}".format(expense_id))


def cmd_payment_add(args, data):
    sender = core.require_member(data, args.sender)
    receiver = core.require_member(data, args.receiver)
    if sender == receiver:
        raise KittyError("someone can't pay themselves back")
    amount = core.parse_money(args.amount)
    currency = (core.parse_currency(args.currency) if args.currency
                else data["currency"])
    day = core.parse_date(args.date) if args.date else core.today()
    base_cents = core.to_base_cents(data, amount, currency)

    payment_id = data["next_payment_id"]
    data["next_payment_id"] += 1
    data["payments"].append({
        "id": payment_id,
        "date": day,
        "from": sender,
        "to": receiver,
        "amount": "{:.2f}".format(amount),
        "currency": currency,
        "base_amount": fmt(base_cents),
        "seq": next_seq(data),
    })


def cmd_rate_set(args, data):
    currency = core.parse_currency(args.currency)
    if currency == data["currency"]:
        raise KittyError("{} is the main currency; its rate is always 1".format(currency))
    rate = core.parse_positive(args.rate, "rate")
    data["rates"][currency] = str(rate)


def cmd_balances(args, data):
    return {name: fmt(c) for name, c in core.balances(data).items()}


def cmd_settle(args, data):
    return core.settle(data)


def cmd_history(args, data):
    return core.history(data, core.require_member(data, args.name))


def cmd_report(args, data):
    return core.category_report(data)


EXPORT_COLUMNS = ["id", "date", "payer", "description", "amount",
                  "currency", "category", "base_amount"]


def cmd_export(args, data):
    try:
        with open(args.file, "w", newline="", encoding="utf-8") as f:
            writer = csv.writer(f)
            writer.writerow(EXPORT_COLUMNS)
            for e in data["expenses"]:
                writer.writerow([e[col] for col in EXPORT_COLUMNS])
    except OSError as e:
        raise KittyError("couldn't write {}: {}".format(args.file, e.strerror or e))


def next_seq(data):
    """A counter that remembers the order things were entered in."""
    seq = data["next_seq"]
    data["next_seq"] += 1
    return seq


# ----------------------------------------------------------------- parser

def build_parser():
    parser = Parser(prog="python3 -m kitty",
                    description="Keep track of shared costs and who owes whom.")
    commands = parser.add_subparsers(dest="command", metavar="COMMAND")
    commands.required = True

    p = commands.add_parser("init", help="start a new kitty in this folder")
    p.add_argument("currency", help="main currency, e.g. EUR")
    p.set_defaults(func=cmd_init, needs_data=False)

    member = commands.add_parser("member", help="add, remove or list people")
    member_cmds = member.add_subparsers(dest="action", metavar="ACTION")
    member_cmds.required = True
    p = member_cmds.add_parser("add", help="add someone to the group")
    p.add_argument("name")
    p.set_defaults(func=cmd_member_add, changes=True)
    p = member_cmds.add_parser("remove", help="remove someone from the group")
    p.add_argument("name")
    p.set_defaults(func=cmd_member_remove, changes=True)
    p = member_cmds.add_parser("list", help="list the group")
    p.set_defaults(func=cmd_member_list)

    expense = commands.add_parser("expense", help="add, list or remove expenses")
    expense_cmds = expense.add_subparsers(dest="action", metavar="ACTION")
    expense_cmds.required = True
    p = expense_cmds.add_parser("add", help="record something someone paid for")
    p.add_argument("payer")
    p.add_argument("amount")
    p.add_argument("description", nargs="+")
    p.add_argument("--among", metavar="A,B",
                   help="split equally between only these people")
    p.add_argument("--exact", metavar="A=30,B=20", help="split by exact amounts")
    p.add_argument("--shares", metavar="A=2,B=1", help="split by shares")
    p.add_argument("--percent", metavar="A=60,B=40", help="split by percentages")
    p.add_argument("--currency", help="currency it was paid in")
    p.add_argument("--date", metavar="YYYY-MM-DD", help="date (default: today)")
    p.add_argument("--category", help="category (default: other)")
    p.set_defaults(func=cmd_expense_add, changes=True)
    p = expense_cmds.add_parser("list", help="list all expenses")
    p.set_defaults(func=cmd_expense_list)
    p = expense_cmds.add_parser("remove", help="remove an expense by ID")
    p.add_argument("id")
    p.set_defaults(func=cmd_expense_remove, changes=True)

    payment = commands.add_parser("payment", help="record someone paying someone back")
    payment_cmds = payment.add_subparsers(dest="action", metavar="ACTION")
    payment_cmds.required = True
    p = payment_cmds.add_parser("add", help="record a payment")
    p.add_argument("sender", metavar="FROM")
    p.add_argument("receiver", metavar="TO")
    p.add_argument("amount")
    p.add_argument("--currency", help="currency it was paid in")
    p.add_argument("--date", metavar="YYYY-MM-DD", help="date (default: today)")
    p.set_defaults(func=cmd_payment_add, changes=True)

    rate = commands.add_parser("rate", help="set exchange rates")
    rate_cmds = rate.add_subparsers(dest="action", metavar="ACTION")
    rate_cmds.required = True
    p = rate_cmds.add_parser("set", help="one CURRENCY is worth RATE of the main currency")
    p.add_argument("currency")
    p.add_argument("rate")
    p.set_defaults(func=cmd_rate_set, changes=True)

    p = commands.add_parser("balances", help="who is up or down overall")
    p.set_defaults(func=cmd_balances)
    p = commands.add_parser("settle", help="suggest payments to even things out")
    p.set_defaults(func=cmd_settle)
    p = commands.add_parser("history", help="everything that affected one person")
    p.add_argument("name")
    p.set_defaults(func=cmd_history)
    p = commands.add_parser("report", help="each person's spending by category")
    p.set_defaults(func=cmd_report)
    p = commands.add_parser("export", help="save the expenses to a CSV file")
    p.add_argument("file")
    p.set_defaults(func=cmd_export)

    return parser


def main(argv=None):
    args = build_parser().parse_args(argv)
    try:
        if getattr(args, "needs_data", True):
            data = core.load()
            result = args.func(args, data)
            if getattr(args, "changes", False):
                core.save(data)
            if result is not None:
                print(json.dumps(result, ensure_ascii=False))
        else:
            args.func(args)
    except KittyError as e:
        print("error: {}".format(e), file=sys.stderr)
        return 1
    except OSError as e:
        print("error: {}".format(e), file=sys.stderr)
        return 1
    return 0
import sys

from .cli import main

sys.exit(main())
